export function ingredientsByCategory(category) {
  return Object.entries(ingredients).filter(([,x]) => x.category === category).map(([slug,x]) => ({ slug, ...x }));
}
export function getIngredient(slug) { return ingredients[slug] ? { slug, ...ingredients[slug] } : null; }
